@router.post("/api/remediation/manual/{vuln_id}")
def manual_remediation(vuln_id: str, body: ManualRemediationModel):
    try:
        with db_manager.get_db_cursor() as cur:
            # 1. Update vulnerability_log status and summary
            manual_note = f"\n\n**[REMEDIACIÓN MANUAL - {datetime.now().strftime('%Y-%m-%d %H:%M')}]**\n**Solución:** {body.solution}\n**Motivo:** {body.reason}"
            cur.execute("""
                UPDATE public.vulnerability_log 
                SET status = 'RESOLVED',
                    executive_summary = COALESCE(executive_summary, '') || %s
                WHERE id = %s
            """, (manual_note, vuln_id))
            
            # 2. Check if remediation_history exists
            cur.execute("SELECT id FROM public.remediation_history WHERE vuln_id = %s", (vuln_id,))
            exists = cur.fetchone()
            
            log_content = f"Manual Solution: {body.solution}\nReason: {body.reason}"
            
            if exists:
                cur.execute("""
                    UPDATE public.remediation_history SET
                        executed_bool = TRUE,
                        approval_token = 'MANUAL',
                        executed_at = NOW(),
                        log_output = %s
                    WHERE vuln_id = %s
                """, (log_content, vuln_id))
            else:
                cur.execute("""
                    INSERT INTO public.remediation_history (vuln_id, executed_bool, approval_token, executed_at, log_output, can_automate)
                    VALUES (%s, TRUE, 'MANUAL', NOW(), %s, FALSE)
                """, (vuln_id, log_content))
            
            return {"status": "success", "message": "Vulnerability marked as manually remediated."}
    except Exception as e:
        print(f"❌ Error in manual remediation: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/api/investigate/runtime")
def investigate_alert(data: dict):
    alert_id = data.get("alert_id")
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT * FROM public.runtime_alerts WHERE id = %s", (alert_id,))
            alert = cur.fetchone()
        
        if not alert:
            raise HTTPException(status_code=404, detail="Alert not found")
            
        prompt = f"""
        Analiza esta alerta de seguridad en tiempo real y proporciona un reporte ultra-conciso para un CISO:
        
        ALERTA: {alert['rule_name']}
        PRIORIDAD: {alert['priority']}
        DETALLE: {alert['alert_text']}
        TIMESTAMP: {alert['detected_at']}
        
        Proporciona el resultado en JSON con:
        - "contexto": ¿Qué significa esto técnicamente?
        - "riesgo": Nivel de peligro real para el negocio.
        - "accion_inmediata": [Lista de 3 pasos críticos a seguir]
        - "remediation_script": "Comando bash exacto o script para mitigar esta amenaza de inmediato. Usa '\\n' para saltos de línea."
        
        NOTA OBLIGATORIA: Si el activo no es un contenedor (ej. servidor o máquina virtual), DEBES incluir explícitamente en el último paso de 'accion_inmediata' la siguiente instrucción de instalación del agente Wazuh: "Para habilitar remediación automática, ejecute: curl -sO https://packages.wazuh.com/4.x/apt/pool/main/w/wazuh-agent/wazuh-agent_4.x_amd64.deb && sudo dpkg -i wazuh-agent*.deb"
        """
        
        # Use the shared 4-provider cascade (Groq -> Gemini -> NVIDIA -> OpenRouter) instead of
        # two hardcoded model names that have both been retired upstream (gemini-1.5-flash-latest
        # 404s, llama-3.3-70b-versatile 404s) -- that was the "The model ... does not exist"
        # error the user reported. call_ai_cascade returns the raw text of the first provider
        # that answers, or None if all are down.
        import centinela
        raw = centinela.call_ai_cascade(prompt, want_json=True)
        if raw:
            txt = raw.strip()
            if txt.startswith("```"):
                txt = txt.split("```", 2)[1]
                if txt.lstrip().lower().startswith("json"):
                    txt = txt.lstrip()[4:]
            start, end = txt.find("{"), txt.rfind("}")
            if start != -1 and end != -1 and end > start:
                try:
                    return json.loads(txt[start:end + 1])
                except json.JSONDecodeError:
                    pass
            # Provider answered but not with parseable JSON -- hand the prose back rather than
            # pretend it failed.
            return {
                "contexto": txt,
                "riesgo": alert["priority"],
                "accion_inmediata": ["Revisar el detalle del análisis anterior", "Triaje manual del activo afectado"],
            }
        raise Exception("Todos los proveedores de IA no disponibles (cuota/clave/timeout)")

    except Exception as e:
        print(f"Critical error in investigation: {e}")
        return {
            "contexto": f"Error crítico de comunicación con el motor de IA: {str(e)}",
            "riesgo": "CRÍTICO (SIN ANALIZAR)",
            "accion_inmediata": ["Revisar logs en /app/logs/security.log", "Ejecutar triaje manual", "Reiniciar agentes de IA"]
        }


class TicketModel(BaseModel):
    title: str
    description: str
    target: str # "redmine" or "gitea"


@router.post("/api/remediation/{vuln_id}/ticket")
def create_soar_ticket(vuln_id: str, body: TicketModel):
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT v.cve_id, COALESCE(v.real_severity, v.severity) AS severity, i.asset_name, v.description
                FROM public.vulnerability_log v
                JOIN public.infra_inventory i ON v.asset_id = i.id
                WHERE v.id = %s
            """, (vuln_id,))
            vuln = cur.fetchone()
        
        if not vuln:
            raise HTTPException(status_code=404, detail="Vulnerability not found")
            
        desc = f"""⚠️ INCIDENT SECURITY TICKET
Asset: {vuln['asset_name']}
CVE/ID: {vuln['cve_id']}
Severity: {vuln['severity']}

Description:
{vuln['description']}

Manual Solution Details:
{body.description}
"""
        
        from core import ticketing
        target = body.target.lower().strip()
        if target not in ticketing.TARGETS:
            raise HTTPException(status_code=400, detail=f"target debe ser uno de {ticketing.TARGETS}")
        try:
            return ticketing.send_ticket(target, vuln, desc)
        except ticketing.TicketingNotConfigured as e:
            raise HTTPException(status_code=503, detail=str(e))
        except ticketing.TicketingError as e:
            raise HTTPException(status_code=502, detail=str(e))
    except HTTPException:
        raise                      # 404/400/502/503 above are answers, not crashes (the blanket handler used to turn them all into 500)
    except Exception as e:
        logger.error("create_soar_ticket failed", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e))



# ========================================================================================
# Item 3 (2026-08-27): finding_suppressions -- learned false-positive / accepted-risk memory.
# CodeRabbit records "this pattern is not a bug here" from reviewer feedback and stops
# resurfacing it. The equivalent here: an analyst records a suppression keyed on any
# combination of asset_id / cve_id / url_path_pattern (LIKE) / fingerprint_hash, and
# core.deduplication_engine.log_finding_deduplicated() parks every future match in SUPPRESSED
# instead of reopening it -- while still counting the re-detection on the suppression row so
# "this is still being flagged by the scanner" stays visible.
# ========================================================================================

_VALID_SUPPRESSION_SCOPES = {"FALSE_POSITIVE", "ACCEPTED_RISK", "WONT_FIX"}



class SuppressionModel(BaseModel):
    asset_id: Optional[str] = None
    cve_id: Optional[str] = None
    url_path_pattern: Optional[str] = None
    fingerprint_hash: Optional[str] = None
    reason: Optional[str] = None
    scope: Optional[str] = "FALSE_POSITIVE"
    created_by: Optional[str] = "analyst"
    expires_at: Optional[str] = None  # ISO8601 timestamp; omit/null = permanent



@router.get("/api/suppressions")
def list_suppressions(active_only: bool = True):
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            q = """
                SELECT s.*, i.asset_name
                FROM public.finding_suppressions s
                LEFT JOIN public.infra_inventory i ON s.asset_id = i.id
            """
            if active_only:
                q += " WHERE s.active = TRUE"
            q += " ORDER BY s.id DESC LIMIT 1000"
            cur.execute(q)
            return {"suppressions": cur.fetchall()}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.post("/api/suppressions")
def create_suppression(body: SuppressionModel):
    if not (body.asset_id or body.cve_id or body.url_path_pattern or body.fingerprint_hash):
        raise HTTPException(
            status_code=400,
            detail="At least one of asset_id, cve_id, url_path_pattern, fingerprint_hash is "
                   "required -- an all-NULL suppression would mute every finding.")
    if not body.reason or not body.reason.strip():
        raise HTTPException(status_code=400, detail="reason is required")
    scope = (body.scope or "FALSE_POSITIVE").upper()
    if scope not in _VALID_SUPPRESSION_SCOPES:
        raise HTTPException(status_code=400,
                            detail=f"scope must be one of {sorted(_VALID_SUPPRESSION_SCOPES)}")
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                INSERT INTO public.finding_suppressions
                (asset_id, cve_id, url_path_pattern, fingerprint_hash, reason, scope, created_by, expires_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING *
            """, (body.asset_id, body.cve_id, body.url_path_pattern, body.fingerprint_hash,
                  body.reason.strip(), scope, body.created_by or "analyst", body.expires_at))
            row = cur.fetchone()

            # Retro-suppress rows already in the log that match, so the effect is immediate and
            # not deferred to the next scan cycle. RESOLVED rows are left alone.
            cur.execute("""
                UPDATE public.vulnerability_log v
                SET status = 'SUPPRESSED'
                WHERE v.status NOT IN ('SUPPRESSED', 'RESOLVED')
                  AND (%(asset_id)s IS NULL OR v.asset_id IS NOT DISTINCT FROM %(asset_id)s)
                  AND (%(cve_id)s IS NULL OR v.cve_id = %(cve_id)s)
                  AND (%(fp)s IS NULL OR v.fingerprint_hash = %(fp)s)
                  AND (%(url)s IS NULL OR COALESCE(v.url_path, '') LIKE %(url)s)
                RETURNING v.id
            """, {"asset_id": body.asset_id, "cve_id": body.cve_id,
                  "fp": body.fingerprint_hash, "url": body.url_path_pattern})
            retro_ids = [r["id"] for r in cur.fetchall()]

        from core import agent_ledger
        agent_ledger.record_action(
            agent_ledger.ACTION_SUPPRESSION_CREATED,
            f"Supresión creada ({scope}) por {row['created_by']}: {body.reason.strip()[:200]}",
            entity_type="suppression", entity_id=row["id"], asset_id=body.asset_id,
            detail={"predicates": {"cve_id": body.cve_id,
                                   "url_path_pattern": body.url_path_pattern,
                                   "fingerprint_hash": body.fingerprint_hash},
                    "retro_suppressed": retro_ids},
            actor=f"analyst:{row['created_by']}", outcome="success",
        )
        return {"status": "created", "suppression": row, "retro_suppressed_ids": retro_ids}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



class SuppressionReviewModel(BaseModel):
    reviewer: Optional[str] = "analyst"
    note: Optional[str] = None



@router.get("/api/suppression-proposals")
def list_suppression_proposals(status: str = "PENDING"):
    """AI-proposed suppressions awaiting human review (created by centinela.py's correlation loop when
    the AI concludes a finding has NO real risk). status: PENDING | APPROVED | REJECTED | ALL."""
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            where = "WHERE s.created_by = 'centinela-ai' AND s.review_status IS NOT NULL"
            params = []
            if status.upper() != "ALL":
                where += " AND s.review_status = %s"
                params.append(status.upper())
            cur.execute(f"""
                SELECT s.id, s.asset_id, i.asset_name, s.cve_id, s.reason, s.review_status, s.active,
                       s.created_at, s.reviewed_by, s.reviewed_at, s.review_note,
                       (SELECT COUNT(*) FROM public.vulnerability_log v
                         WHERE v.asset_id = s.asset_id AND v.cve_id = s.cve_id
                           AND v.risk_verdict IN ('CONFIRMED_NO_RISK', 'ANALYST_OVERRIDDEN')
                           AND v.status NOT IN ('RESOLVED')) AS affected_count,
                       (SELECT MAX(v.severity) FROM public.vulnerability_log v
                         WHERE v.asset_id = s.asset_id AND v.cve_id = s.cve_id
                           AND v.risk_verdict IN ('CONFIRMED_NO_RISK', 'ANALYST_OVERRIDDEN')) AS tool_severity,
                       (SELECT MAX(v.business_impact) FROM public.vulnerability_log v
                         WHERE v.asset_id = s.asset_id AND v.cve_id = s.cve_id
                           AND v.risk_verdict IN ('CONFIRMED_NO_RISK', 'ANALYST_OVERRIDDEN')) AS explanation,
                       (SELECT (ARRAY_AGG(v.url_path))[1:6] FROM public.vulnerability_log v
                         WHERE v.asset_id = s.asset_id AND v.cve_id = s.cve_id
                           AND v.risk_verdict IN ('CONFIRMED_NO_RISK', 'ANALYST_OVERRIDDEN')
                           AND v.status NOT IN ('RESOLVED')) AS sample_locations
                FROM public.finding_suppressions s
                LEFT JOIN public.infra_inventory i ON s.asset_id = i.id
                {where}
                ORDER BY s.created_at DESC LIMIT 500
            """, params)
            return {"proposals": cur.fetchall()}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.get("/api/risk-verdicts/conditional")
def list_conditional_verdicts():
    """Findings whose AI verdict depends on an UNVERIFIED assumption (risk_verdict='CONDITIONAL'):
    severity is kept as the scanner reported; a human should verify the assumption."""
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT i.asset_name, v.cve_id, MAX(v.severity) AS tool_severity, COUNT(*) AS occurrences,
                       MAX(v.business_impact) AS explanation
                FROM public.vulnerability_log v JOIN public.infra_inventory i ON v.asset_id = i.id
                WHERE v.risk_verdict = 'CONDITIONAL' AND v.status NOT IN ('RESOLVED', 'SUPPRESSED')
                GROUP BY i.asset_name, v.cve_id ORDER BY i.asset_name, v.cve_id
            """)
            return {"conditional": cur.fetchall()}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.post("/api/suppression-proposals/{sid}/approve")
def approve_suppression_proposal(sid: str, body: SuppressionReviewModel = SuppressionReviewModel()):
    """Analyst agrees the finding has no real risk. Suppresses ONLY the specific findings the AI
    assessed (one fingerprint-keyed suppression per finding) -- deliberately NOT a blanket
    asset+cve_id mute, which would also silence a future, genuinely dangerous occurrence of the
    same rule on that asset (e.g. Math.random() used for demo data vs. for a session token)."""
    try:
        reviewer = body.reviewer or "analyst"
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                UPDATE public.finding_suppressions
                SET review_status = 'APPROVED', active = FALSE, reviewed_by = %s, reviewed_at = NOW(), review_note = %s
                WHERE id = %s AND review_status = 'PENDING' AND created_by = 'centinela-ai'
                RETURNING id, asset_id, cve_id, reason
            """, (reviewer, body.note, sid))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="Propuesta no encontrada o ya revisada")
            cur.execute("""
                SELECT id, fingerprint_hash FROM public.vulnerability_log
                WHERE asset_id = %s AND cve_id = %s AND risk_verdict = 'CONFIRMED_NO_RISK'
                  AND status NOT IN ('SUPPRESSED', 'RESOLVED')
            """, (row["asset_id"], row["cve_id"]))
            targets = cur.fetchall()
            for t in targets:
                if t["fingerprint_hash"]:
                    cur.execute("""
                        INSERT INTO public.finding_suppressions
                        (asset_id, cve_id, fingerprint_hash, reason, scope, created_by, active,
                         review_status, reviewed_by, reviewed_at, review_note)
                        VALUES (%s, %s, %s, %s, 'FALSE_POSITIVE', %s, TRUE, 'APPROVED', %s, NOW(), %s)
                    """, (row["asset_id"], row["cve_id"], t["fingerprint_hash"], row["reason"],
                          f"analyst:{reviewer}", reviewer, body.note))
            cur.execute("""
                UPDATE public.vulnerability_log SET status = 'SUPPRESSED'
                WHERE id = ANY(%s::uuid[])
            """, ([t["id"] for t in targets],))
        from core import agent_ledger
        agent_ledger.record_action(
            agent_ledger.ACTION_SUPPRESSION_CREATED,
            f"Propuesta de supresión de IA APROBADA por {reviewer}: {row['cve_id']} ({len(targets)} hallazgos)",
            entity_type="suppression", entity_id=sid, asset_id=row["asset_id"],
            detail={"suppressed_findings": len(targets), "note": body.note},
            actor=f"analyst:{reviewer}", outcome="success",
        )
        return {"status": "approved", "id": sid, "suppressed_findings": len(targets)}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.post("/api/suppression-proposals/{sid}/reject")
def reject_suppression_proposal(sid: str, body: SuppressionReviewModel = SuppressionReviewModel()):
    """Analyst disagrees with the AI: the matching findings go back to the scanner's raw severity
    (real_severity cleared, risk_verdict='ANALYST_OVERRIDDEN' so no later backfill re-applies the AI
    verdict) and their SLA deadline is recomputed from that raw severity."""
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                UPDATE public.finding_suppressions
                SET review_status = 'REJECTED', active = FALSE, reviewed_by = %s, reviewed_at = NOW(), review_note = %s
                WHERE id = %s AND review_status = 'PENDING' AND created_by = 'centinela-ai'
                RETURNING id, asset_id, cve_id
            """, (body.reviewer or "analyst", body.note, sid))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="Propuesta no encontrada o ya revisada")
            cur.execute("""
                SELECT id, severity, detected_at FROM public.vulnerability_log
                WHERE asset_id = %s AND cve_id = %s AND risk_verdict = 'CONFIRMED_NO_RISK'
            """, (row["asset_id"], row["cve_id"]))
            reverted = 0
            for v in cur.fetchall():
                due = (v["detected_at"] or datetime.utcnow()) + deduplication_engine.get_sla_delta(v["severity"])
                cur.execute("""
                    UPDATE public.vulnerability_log
                    SET real_severity = NULL, risk_verdict = 'ANALYST_OVERRIDDEN', sla_due_date = %s WHERE id = %s
                """, (due, v["id"]))
                reverted += 1
        from core import agent_ledger
        agent_ledger.record_action(
            agent_ledger.ACTION_SUPPRESSION_CREATED,
            f"Propuesta de supresión de IA RECHAZADA por {body.reviewer}: {row['cve_id']} ({reverted} hallazgos vuelven a severidad de la herramienta)",
            entity_type="suppression", entity_id=sid, asset_id=row["asset_id"],
            detail={"reverted_findings": reverted, "note": body.note},
            actor=f"analyst:{body.reviewer}", outcome="success",
        )
        return {"status": "rejected", "id": sid, "reverted_findings": reverted}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.delete("/api/suppressions/{sid}")
def deactivate_suppression(sid: str):
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute(
                "UPDATE public.finding_suppressions SET active = FALSE WHERE id = %s RETURNING id",
                (sid,))
            row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Suppression not found")
        return {"status": "deactivated", "id": sid}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.post("/api/remediation/{vuln_id}/suppress")
def suppress_from_soar(vuln_id: str, body: SuppressionModel):
    """
    Convenience path for the SOAR UI: suppress this exact finding. Keys the suppression on the
    finding's own fingerprint_hash so ONLY this finding is muted (not every finding sharing its
    cve_id), and parks the row in SUPPRESSED immediately.
    """
    scope = (body.scope or "FALSE_POSITIVE").upper()
    if scope not in _VALID_SUPPRESSION_SCOPES:
        raise HTTPException(status_code=400,
                            detail=f"scope must be one of {sorted(_VALID_SUPPRESSION_SCOPES)}")
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT v.id, v.cve_id, v.asset_id, v.fingerprint_hash, v.url_path,
                       COALESCE(i.asset_name, '(sin activo)') AS asset_name
                FROM public.vulnerability_log v
                LEFT JOIN public.infra_inventory i ON v.asset_id = i.id
                WHERE v.id = %s
            """, (vuln_id,))
            vuln = cur.fetchone()
            if not vuln:
                raise HTTPException(status_code=404, detail="Vulnerability not found")
            if not vuln["fingerprint_hash"]:
                raise HTTPException(
                    status_code=409,
                    detail="Finding has no fingerprint_hash; cannot key a precise suppression on it.")
            reason = (body.reason or "").strip() or f"Suprimido desde SOAR para {vuln['cve_id']}"
            cur.execute("""
                INSERT INTO public.finding_suppressions
                (asset_id, cve_id, fingerprint_hash, reason, scope, created_by)
                VALUES (%s, %s, %s, %s, %s, %s)
                RETURNING *
            """, (vuln["asset_id"], vuln["cve_id"], vuln["fingerprint_hash"],
                  reason, scope, body.created_by or "analyst"))
            supp = cur.fetchone()
            cur.execute("UPDATE public.vulnerability_log SET status = 'SUPPRESSED' WHERE id = %s",
                        (vuln_id,))

        from core import agent_ledger
        agent_ledger.record_action(
            agent_ledger.ACTION_FINDING_SUPPRESSED,
            f"Hallazgo {vuln['cve_id']} en {vuln['asset_name']} suprimido desde SOAR ({scope}): {reason[:200]}",
            entity_type="vulnerability", entity_id=vuln_id, asset_id=vuln["asset_id"],
            detail={"suppression_id": supp["id"], "scope": scope},
            actor=f"analyst:{body.created_by or 'analyst'}", outcome="success",
        )
        return {"status": "suppressed", "vuln_id": vuln_id, "suppression": supp}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.get("/api/stats/soar-roi")
def get_soar_roi():
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT AVG(EXTRACT(EPOCH FROM (r.executed_at - v.detected_at))) / 60 as avg_minutes
                FROM public.remediation_history r
                JOIN public.vulnerability_log v ON r.vuln_id = v.id
                WHERE r.executed_bool = TRUE AND r.executed_at IS NOT NULL
                  AND r.executed_at >= v.detected_at
                  AND (r.executed_at - v.detected_at) < interval '1 hour'
            """)
            avg_min = cur.fetchone()["avg_minutes"]
            avg_min = avg_min if avg_min is not None else 0.0
            
            cur.execute("""
                SELECT 
                    COUNT(CASE WHEN approval_token = 'APPROVED' AND executed_bool = TRUE THEN 1 END) as success,
                    COUNT(CASE WHEN approval_token = 'APPROVED' THEN 1 END) as total
                FROM public.remediation_history
            """)
            eff_res = cur.fetchone()
            success_count = eff_res["success"] or 0
            total_count = eff_res["total"] or 0
            effectiveness = (success_count / total_count * 100) if total_count > 0 else 0.0
            
            cur.execute("""
                SELECT 
                    COUNT(CASE WHEN approval_token = 'APPROVED' AND executed_bool = TRUE THEN 1 END) as ai,
                    COUNT(CASE WHEN approval_token = 'MANUAL' AND executed_bool = TRUE THEN 1 END) as manual
                FROM public.remediation_history
            """)
            comparison = cur.fetchone()
            
            return {
                "avg_remediation_time_minutes": round(avg_min, 1),
                "effectiveness_rate_percentage": round(effectiveness, 1),
                "comparison": {
                    "ai_resolved": comparison["ai"] or 0,
                    "manual_resolved": comparison["manual"] or 0
                }
            }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
